-- Venue Live Guest "Wedding Keliling Dunia". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara worldtour), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'worldtour', 'Wedding Keliling Dunia (travel)', 'worldtour', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 137, 'center 38%',
  $t${"name":"Keliling Dunia","orn":"diamond","ui":{"ivory":"#FBF6EE","white":"#FFFFFF","soft":"#F3E6D3","soft2":"#E2B3BF","accent":"#2F3E78","deep":"#1D2A57","ink":"#1F2747","mute":"#6E7595","line":"#E9DCC6","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FBF3E6","ink":"#1F2747","accent":"#2F3E78","gold":"#C9A24A","leaf":"#F3E6D3","hbg":"rgba(251,246,238,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(29,42,87,.88)","acc":"#F2C86B","on":"#1F2747"},"scr":{"wine":"#1D2A57","veil":"251,246,238"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'worldtour');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/worldtour/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/worldtour/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/worldtour/stall_snacks.webp","w":6.2,"x":15.6,"z":-0.8},"stall_candy":{"url":"/assets/live-decor/worldtour/stall_candy.webp","w":5.8,"x":-14.5,"z":4.5},"stall_drinks":{"url":"/assets/live-decor/worldtour/stall_drinks.webp","w":9.2,"x":-9.4,"z":-11.5},"photobooth":{"url":"/assets/live-decor/worldtour/photobooth.webp","w":6.4},"claw":{"url":"/assets/live-decor/worldtour/claw.webp","w":8.6},"arch":{"url":"/assets/live-decor/worldtour/arch.webp"},"fountain":{"url":"/assets/live-decor/worldtour/fountain.webp","w":7.8,"x":9.3,"z":-15.5},"sign":{"url":"/assets/live-decor/worldtour/sign.webp","w":1.7,"x":-5.6,"z":9},"easel":{"url":"/assets/live-decor/worldtour/easel.webp","w":4.8,"x":5.2,"z":10.0},"table":{"url":"/assets/live-decor/worldtour/table.webp","w":3.4,"x":-8.8,"z":3.6},"banner":{"url":"/assets/live-decor/worldtour/banner.webp","w":1.0},"gifts":{"url":"/assets/live-decor/worldtour/gifts.webp","w":1.9},"lamp":{"url":"/assets/live-decor/worldtour/lamp.webp","w":1.4,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/worldtour/rope.webp","w":1.3,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/worldtour/planter.webp","w":1.4,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/worldtour/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/worldtour/av_host.webp","name":"Pengantin"},"av_l1":{"url":"/assets/live-decor/worldtour/av_l1.webp","name":"Kak Kamera"},"av_l2":{"url":"/assets/live-decor/worldtour/av_l2.webp","name":"Kak Topi Rompi"},"av_l3":{"url":"/assets/live-decor/worldtour/av_l3.webp","name":"Kak Batik Navy"},"av_p1":{"url":"/assets/live-decor/worldtour/av_p1.webp","name":"Kak Hijab Topi"},"av_p2":{"url":"/assets/live-decor/worldtour